function first(xs: int[] | null): int | null {
  if (xs !== null) { return xs[0]; }
  return null;
}
export function test(): int {
  let a: int[] = [7, 8];
  let got: int | null = first(a);
  let none: int | null = first(null);
  let r: int = 0;
  if (got !== null) { r = r + got; }
  if (none === null) { r = r + 1; }
  return r;
}

function total(xs: (int | null)[]): int {
  let r: int = 0;
  let i: int = 0;
  while (i < xs.length) {
    let e: int | null = xs[i];
    if (e !== null) { r = r + e; }
    i = i + 1;
  }
  return r;
}
export function test(): int {
  let xs: (int | null)[] = [];
  xs[0] = 1;
  xs[1] = null;
  xs[2] = 3;
  return total(xs);
}

class User { name: string = ""; }
function greet(u: User | null): string {
  if (u !== null) { return u.name; }
  return "nobody";
}
export function test(): int {
  let a: User = { name: "ada" };
  let s: string = greet(a);
  let t: string = greet(null);
  if (s === "ada" && t === "nobody") { return 1; }
  return 0;
}

class Pair { x: int = 0; }
function sig(a: int[], p: Pair | null, xs: string[] | null): int | null {
  let r: int = 0;
  if (a.length === 2) { r = r + a[0]; }
  if (p !== null) { r = r + p.x; }
  if (xs === null) { r = r + 1; }
  return r;
}
export function test(): int {
  let pp: Pair = { x: 4 };
  let out: int | null = sig([5, 0], pp, null);
  if (out !== null) { return out; }
  return 99;
}

class Pt { x: int = 0; }
function shift(ps: Pt[]): Pt {
  return ps[0];
}
export function test(): int {
  let first: Pt = { x: 30 };
  let second: Pt = { x: 40 };
  let ps: Pt[] = [first, second];
  let p: Pt = shift(ps);
  return p.x;
}

class Pt { x: int = 0; }
function sum(ps: (Pt | null)[]): int {
  let r: int = 0;
  let i: int = 0;
  while (i < ps.length) {
    let e: Pt | null = ps[i];
    if (e !== null) { r = r + e.x; }
    i = i + 1;
  }
  return r;
}
export function test(): int {
  let ps: (Pt | null)[] = [];
  let p: Pt = { x: 1 };
  ps[0] = p;
  ps[1] = null;
  let q: Pt = { x: 2 };
  ps[2] = q;
  return sum(ps);
}

class Pt { x: int = 0; }
function head(ps: Pt[] | null): Pt | null {
  if (ps !== null) { return ps[0]; }
  return null;
}
export function test(): int {
  let ps: Pt[] = [];
  let p: Pt = { x: 9 };
  ps[0] = p;
  let h: Pt | null = head(ps);
  let r: int = 0;
  if (h !== null) { r = r + h.x; }
  let none: Pt | null = head(null);
  if (none === null) { r = r + 1; }
  return r;
}

function count(xs: (int | null)[] | null): int {
  if (xs !== null) {
    let arr: (int | null)[] = xs;
    let r: int = 0;
    let i: int = 0;
    while (i < arr.length) {
      let e: int | null = arr[i];
      if (e !== null) { r = r + e; }
      i = i + 1;
    }
    return r;
  }
  return -1;
}
export function test(): int {
  let xs: (int | null)[] = [];
  xs[0] = 2;
  xs[1] = null;
  let got: int = count(xs);
  let none: int = count(null);
  return got + none + 3;
}

